const skills=['Listening','Speaking','Reading','Writing'];
const norm=s=>String(s??'').normalize('NFC').trim().replace(/\s+/g,' ').toLowerCase();
export function v46LowerLanguageReference(grade,subject){
 if(!['1','2','3'].includes(grade)||!['nepali','english'].includes(subject))throw Error('Invalid lower language reference');
 const nepali=subject==='nepali',forms=nepali?(grade==='1'?cdcPrimaryNepaliForms:cdcNepaliThemeForms[grade]):cdcPrimaryEnglishForms[grade];
 return Object.freeze(Object.entries(forms).map(([unit,form])=>{
  const count=nepali?form.indices.length:form.groups.reduce((a,b)=>a+b,0);
  let rows;
  if(nepali){
   if(grade!=='1')rows=form.indices.map(i=>{const [title,aspect,tool]=cdcNepaliThemeRows[grade][i];return {title,aspect,tool}});
   else {
    const base=catalogue['1:nepali'].filter(r=>r[0]===unit);
    const mapped=form.order?form.order.map(ref=>typeof ref==='number'?base[ref]:[unit,ref]):base;
    if(mapped.length===count&&mapped.every(Boolean))rows=mapped.map(([,title],i)=>{
     const index=form.indices[i], [aspect,tool]=cdcPrimaryNepaliTools[index];
     return {title:(index===3&&form.vowels)||(index===13&&form.consonants)||title,aspect:index===0&&form.page===103?'श्रुतिकथन':index===3&&form.page>=105?'सङ्केतन, विसङ्केतन र पठन अभ्यास':aspect,tool:index===7&&form.page===104?'उच्चारण':index===3&&form.page>=105?'श्रवण, उच्चारण र सस्वरवाचन':index===11&&form.page>=105?tool+' र स्थलगत भ्रमण':index===12&&form.page>=108?'मौखिक तथा लिखित प्रयोग':tool};
    });
   }
  }else {
   const base=grade==='1'?catalogue['1:english'].filter(r=>r[0]===unit):form.indices.map(i=>catalogue[grade+':english'][i]);
   const areas=form.groups.flatMap((n,i)=>Array(n).fill(skills[i]));
   if(base.length===count&&base.every(Boolean))rows=base.map((r,i)=>({title:grade==='1'?r[2]:r[1],aspect:areas[i]}));
  }
  const valid=rows?.length===count&&rows.every(r=>Object.values(r).every(v=>typeof v==='string'&&v.trim()))&&new Set(rows.map(r=>norm(r.title))).size===count;
  const page=nepali?form.page:null;
  return Object.freeze({theme:nepali?(form.displayTitle||unit):form.name,en:nepali?'':form.name,count,fullMarks:count*4,page,guide:'lower',status:'v46WorkingReference',indicators:null,scoreBlocks:null,sourceRows:valid?Object.freeze(rows.map(r=>Object.freeze(r))):null,printedPage:nepali,sourceNote:form.note??null});
 }));
}
